package com.tripmateai.controller; import com.tripmateai.dto.request.activity.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.activity.*; import com.tripmateai.service.ActivityService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequiredArgsConstructor public class ActivityController {private final ActivityService service; @PostMapping("/itineraries/{itineraryId}/activities") public ResponseEntity<ApiResponse<ActivityResponse>> create(@PathVariable Long itineraryId,@Valid @RequestBody CreateActivityRequest r){return ResponseUtils.created(service.create(itineraryId,r),"Activity created");} @GetMapping("/itineraries/{itineraryId}/activities") public ResponseEntity<ApiResponse<List<ActivityResponse>>> list(@PathVariable Long itineraryId){return ResponseUtils.success(service.list(itineraryId),"Activities retrieved");} @PutMapping("/itineraries/{itineraryId}/activities/reorder") public ResponseEntity<ApiResponse<Void>> reorder(@PathVariable Long itineraryId,@Valid @RequestBody ReorderActivitiesRequest r){service.reorder(itineraryId,r);return ResponseUtils.success(null,"Activities reordered");} @GetMapping("/activities/{id}") public ResponseEntity<ApiResponse<ActivityResponse>> get(@PathVariable Long id){return ResponseUtils.success(service.get(id),"Activity retrieved");} @PutMapping("/activities/{id}") public ResponseEntity<ApiResponse<ActivityResponse>> update(@PathVariable Long id,@Valid @RequestBody UpdateActivityRequest r){return ResponseUtils.success(service.update(id,r),"Activity updated");} @DeleteMapping("/activities/{id}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id){service.delete(id);return ResponseUtils.success(null,"Activity deleted");}}
